**`intelligence.cjs` — `boostConfidence()` reads two files on every feedback call**

Called from both `getContext()` (line ~545) and `feedback()` (line ~580), this function reads `RANKED_PATH` and `GRAPH_PATH`, modifies them, and writes both back — 4 reads + 2 writes per invocation.

```javascript
// CURRENT — in boostConfidence() at intelligence.cjs:587
function boostConfidence(ids, amount) {
  const ranked = readJSON(RANKED_PATH);   // disk read #1
  // ...
  if (changed) writeJSON(RANKED_PATH, ranked);  // disk write #1

  const graph = readJSON(GRAPH_PATH);     // disk read #2
  // ...
  writeJSON(GRAPH_PATH, graph);           // disk write #2
}

// ALSO: getContext() calls both sessionGet() (reads SESSION_FILE)
// AND boostConfidence() (reads RANKED_PATH again after just reading it above)
```

**Fix**: Cache the loaded objects in module-level variables and mark them dirty, then flush only at `consolidate()`:

```javascript
let _rankedCache = null;
let _rankedDirty = false;

function getRanked() {
  if (_rankedCache) return _rankedCache;
  _rankedCache = readJSON(RANKED_PATH);
  return _rankedCache;
}

function flushRanked() {
  if (_rankedDirty && _rankedCache) {
    writeJSON(RANKED_PATH, _rankedCache);
    _rankedDirty = false;
  }
}

function boostConfidence(ids, amount) {
  const ranked = getRanked();
  // ... mutate ranked in place ...
  _rankedDirty = true;
  // Don't write here — flush in consolidate()
}
```

