**`router.cjs:routeTask()` — lines 29–48**

Every task routing call creates 8 `new RegExp(...)` objects, all from static strings that never change.

```javascript
// CURRENT — router.cjs:32
for (const [pattern, agent] of Object.entries(TASK_PATTERNS)) {
  const regex = new RegExp(pattern, 'i');  // compiled fresh every call
  if (regex.test(taskLower)) { ... }
}
```

**Fix**: Pre-compile once at module load:

```javascript
// Compile once at startup
const COMPILED_PATTERNS = Object.entries(TASK_PATTERNS).map(([pattern, agent]) => ({
  regex: new RegExp(pattern, 'i'),
  agent,
  pattern,
}));

function routeTask(task) {
  const taskLower = task.toLowerCase();
  for (const { regex, agent, pattern } of COMPILED_PATTERNS) {
    if (regex.test(taskLower)) {
      return { agent, confidence: 0.8, reason: `Matched pattern: ${pattern}` };
    }
  }
  return { agent: 'coder', confidence: 0.5, reason: 'Default routing' };
}
```

