**`intelligence.cjs:sessionGet()` / `sessionSet()` — lines 154–174**

Both functions parse and serialize the full session JSON file on every call — even for a single key lookup. `getContext()` calls `sessionGet` + `sessionSet` on each route invocation.

```javascript
// CURRENT — reads entire file, parses JSON, returns one value
function sessionGet(key) {
  const session = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf-8'));
  return key ? (session.context || {})[key] : session.context;
}
```

**Fix**: Keep a module-level in-memory session object and only persist on explicit flush:

```javascript
let _session = null;

function _loadSession() {
  if (_session) return _session;
  try {
    if (fs.existsSync(SESSION_FILE))
      _session = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf-8'));
  } catch {}
  _session = _session || {};
  return _session;
}

function sessionGet(key) {
  const s = _loadSession();
  return key ? (s.context || {})[key] : s.context;
}

function sessionSet(key, value) {
  const s = _loadSession();
  if (!s.context) s.context = {};
  s.context[key] = value;
  s.updatedAt = new Date().toISOString();
  // Write is deferred to consolidate()/session-end
}

// Call this at session-end:
function flushSession() {
  if (!_session) return;
  try {
    fs.writeFileSync(SESSION_FILE, JSON.stringify(_session, null, 2), 'utf-8');
  } catch {}
}
```

